def transform(grid):
    g = np.array(grid)
    H0, W0 = g.shape
    bg = background(g)
    fgc = [c for c in np.unique(g) if c != bg][0]
    comps = components(g != bg)
    n = len(comps)
    from collections import deque
    encl = []
    for cells in comps:
        wall = np.zeros((H0, W0), bool)
        for (y, x) in cells:
            wall[y, x] = True
        seen = np.zeros((H0, W0), bool)
        dq = deque()
        for y in range(H0):
            for x in range(W0):
                if (y in (0, H0 - 1) or x in (0, W0 - 1)) and not wall[y, x]:
                    seen[y, x] = True
                    dq.append((y, x))
        while dq:
            y, x = dq.popleft()
            for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                ny, nx = y + dy, x + dx
                if 0 <= ny < H0 and 0 <= nx < W0 and not seen[ny, nx] and not wall[ny, nx]:
                    seen[ny, nx] = True
                    dq.append((ny, nx))
        encl.append(~seen & ~wall)
    parent = [None] * n
    for i in range(n):
        y, x = comps[i][0]
        best = None
        for j in range(n):
            if j != i and encl[j][y, x]:
                if best is None or encl[j].sum() < encl[best].sum():
                    best = j
        parent[i] = best
    children = {j: [i for i in range(n) if parent[i] == j] for j in list(range(n)) + [None]}
    boxes = [bbox(c) for c in comps]

    def clusters(ids, a, b):
        order = sorted(ids, key=lambda i: boxes[i][a])
        idx, k, cur = {}, -1, None
        for i in order:
            if cur is None or boxes[i][a] > cur:
                k += 1
                cur = boxes[i][b]
            else:
                cur = max(cur, boxes[i][b])
            idx[i] = k
        return idx, k + 1

    def shift(p, dy, dx):
        if p[0] == 'dot':
            return ('dot', p[1] + dy, p[2] + dx, p[3])
        return ('frame', p[1] + dy, p[2] + dx, p[3] + dy, p[4] + dx)

    def block(i):
        if not children[i]:
            return 3, 3, [('dot', 1, 1, i)]
        h, w, prims, _ = arrange(children[i])
        out = [('frame', 1, 1, h + 2, w + 2)]
        for p in prims:
            out.append(shift(p, 2, 2))
        return h + 4, w + 4, out

    def arrange(ids):
        if not ids:
            return 1, 1, [], []
        ri, nr = clusters(ids, 0, 2)
        ci, nc = clusters(ids, 1, 3)
        blocks = {i: block(i) for i in ids}
        Hs = [1] * nr
        Ws = [1] * nc
        for i in ids:
            Hs[ri[i]] = max(Hs[ri[i]], blocks[i][0])
            Ws[ci[i]] = max(Ws[ci[i]], blocks[i][1])
        rs = [0]
        for r in range(nr - 1):
            rs.append(rs[-1] + Hs[r] - 1)
        cs = [0]
        for c in range(nc - 1):
            cs.append(cs[-1] + Ws[c] - 1)
        prims, places = [], []
        for i in ids:
            bh, bw, bp = blocks[i]
            dy = (Hs[ri[i]] - bh) // 2
            dy -= dy % 2
            dx = (Ws[ci[i]] - bw) // 2
            dx -= dx % 2
            places.append((i, rs[ri[i]] + dy, cs[ci[i]] + dx, bh, bw))
        adjusted = []
        for i, oy, ox, bh, bw in places:
            if not children[i]:
                for axis in (0, 1):
                    choices = []
                    for j, jy, jx, jh, jw in places:
                        if j == i or not children[j]:
                            continue
                        same_band = ri[i] == ri[j] if axis == 0 else ci[i] == ci[j]
                        if not same_band:
                            continue
                        for primitive in blocks[j][2]:
                            if primitive[0] != 'dot':
                                continue
                            leaf = primitive[3]
                            lo, hi = boxes[i][axis], boxes[i][axis + 2]
                            alo, ahi = boxes[leaf][axis], boxes[leaf][axis + 2]
                            if max(lo, alo) <= min(hi, ahi):
                                coordinate = (jy if axis == 0 else jx) + primitive[axis + 1]
                                choices.append((abs((lo + hi) - (alo + ahi)), coordinate))
                    if choices:
                        distance = min(c[0] for c in choices)
                        anchors = {v for d, v in choices if d == distance}
                        if len(anchors) == 1:
                            offset = next(iter(anchors)) - 1
                            bound = rs[-1] + Hs[-1] if axis == 0 else cs[-1] + Ws[-1]
                            if 0 <= offset <= bound - 3:
                                if axis == 0:
                                    oy = offset
                                else:
                                    ox = offset
            adjusted.append((i, oy, ox, bh, bw))
        for i, oy, ox, bh, bw in adjusted:
            for primitive in blocks[i][2]:
                prims.append(shift(primitive, oy, ox))
        return rs[-1] + Hs[-1], cs[-1] + Ws[-1], prims, adjusted

    top = children[None]
    h, w, prims, places = arrange(top)
    ys0, xs0, ys1, xs1 = [], [], [], []
    for (i, oy, ox, bh, bw) in places:
        if children[i]:
            r = (oy + 1, ox + 1, oy + bh - 2, ox + bw - 2)
        else:
            r = (oy, ox, oy + bh - 1, ox + bw - 1)
        ys0.append(r[0]); xs0.append(r[1]); ys1.append(r[2]); xs1.append(r[3])
    Y0, X0 = min(ys0), min(xs0)
    out = np.full((max(ys1) - Y0 + 1, max(xs1) - X0 + 1), bg, dtype=int)
    emit(out, "Allocate a background canvas sized to the nested-frame diagram.")
    for p in prims:
        if p[0] == 'dot':
            out[p[1] - Y0, p[2] - X0] = fgc
            emit(out, "A solid blob becomes a single dot at its layout position.")
        else:
            y0, x0, y1, x1 = p[1] - Y0, p[2] - X0, p[3] - Y0, p[4] - X0
            out[y0, x0:x1 + 1] = fgc
            out[y1, x0:x1 + 1] = fgc
            out[y0:y1 + 1, x0] = fgc
            out[y0:y1 + 1, x1] = fgc
            emit(out, "A closed loop becomes a rectangular frame around its contents.")
    emit(out, "Final diagram of the containment structure.")
    return out
